# Same observed facilities, fixed scenario DGP, and separate realized diagnostics.
if(!exists('retail_pool_diagnostics'))library(creditratingsystem)
.rpc_portfolio<-function(case,product){
 positions<-case$positions;graph<-build_entity_graph(lapply(sort(unique(vapply(positions,function(p)p$entity_id,character(1)))),function(e)list(entity_id=e)),list(),list(policy_id='no-inferred-cross-default',version='1',edge_types=list('CROSS_DEFAULT')),as_of='2024-01-01',known_at='2024-01-01')
 contract<-list(portfolio_id=product,version='1',currency='EUR',as_of='2024-01-01',known_at='2024-01-01',horizon=30,time_unit='days',probability_measure='PHYSICAL',conditioning='initially_performing',event='first_default')
 prepared<-prepare_credit_portfolio(positions,graph,list(policy_id='legal-groups',version='1',edge_types=list('CROSS_DEFAULT'),direction_policy='mutual_only',transitive=TRUE),contract)$value;groups<-as.character(unlist(prepared$default_group_ids));forecast<-setNames(case$predictions,vapply(case$predictions,function(r)r$prediction_id,character(1)));pds<-setNames(lapply(groups,function(g){r<-Filter(function(r)r$default_group_id==g,prepared$positions)[[1]];forecast[[r$position_id]]$pd}),groups);ids<-vapply(positions,function(p)p$position_id,character(1));ead<-vapply(positions,function(p)p$ead,numeric(1));lgd<-vapply(positions,function(p)forecast[[p$position_id]]$lgd,numeric(1))
 for(g in groups)if(length(unique(vapply(Filter(function(r)r$default_group_id==g,prepared$positions),function(r)forecast[[r$position_id]]$pd,numeric(1))))!=1L)stop('Frozen facility PDs must agree within a legal default group')
 states<-as.matrix(expand.grid(rep(list(c(0,1)),length(groups))));states<-states[,ncol(states):1,drop=FALSE];uniforms<-matrix(0,nrow(states),length(groups));weights<-numeric(nrow(states));for(i in seq_len(nrow(states))){uniforms[i,]<-vapply(seq_along(groups),function(j)if(states[i,j]==1)pds[[groups[j]]]/2 else(1+pds[[groups[j]]])/2,numeric(1));weights[i]<-round(prod(vapply(seq_along(groups),function(j)if(states[i,j]==1)pds[[groups[j]]]else 1-pds[[groups[j]]],numeric(1))),12)}
 rows<-function(m)lapply(seq_len(nrow(m)),function(i)as.list(m[i,]));scenario_ids<-paste0('state-',seq_along(weights)-1L);dep<-list(kind='SUPPLIED_DEPENDENT_UNIFORMS',group_ids=as.list(groups));draws<-list(scenario_ids=as.list(scenario_ids),weights=as.list(weights),group_ids=as.list(groups),sampling_design='EXACT_STATES',group_uniforms=rows(uniforms))
 paths<-function(dependence,innovations)list(scenario_ids=innovations$scenario_ids,position_ids=as.list(ids),driver_hash=content_fingerprint(list(dependence_contract=dependence,shared_innovations=innovations))$value,ead=rep(list(as.list(ead)),length(innovations$scenario_ids)),lgd=rep(list(as.list(lgd)),length(innovations$scenario_ids)),guarantee_treatment='NOT_YET_APPLIED')
 simulation<-simulate_credit_portfolio(prepared,pds,dep,draws,paths(dep,draws),levels=c(.8,.95))$value;distribution<-credit_loss_distribution(unlist(simulation$portfolio_loss_paths),weights,scenario_ids=scenario_ids,levels=c(.8,.95),currency='EUR')$value
 allocation<-allocate_expected_shortfall(do.call(rbind,lapply(simulation$net_position_losses,unlist)),weights,scenario_ids=scenario_ids,position_ids=ids,level=.8,currency='EUR',groups=setNames(lapply(positions,function(p)p$household_id),ids))$value
 removal<-incremental_credit_risk(unlist(simulation$portfolio_loss_paths),-vapply(simulation$net_position_losses,function(r)unlist(r)[1],numeric(1)),weights,scenario_ids=scenario_ids,levels=c(.8,.95),currency='EUR',change_id='remove-first-held-facility')$value
 bygroup<-setNames(lapply(groups,function(g)Filter(function(r)r$default_group_id==g,prepared$positions)),groups);initial<-setNames(lapply(groups,function(g)if(pds[[g]]==.1)'A'else'B'),groups)
 value_contract<-list(valuation_id=paste0(product,'-marks'),version='1',currency='EUR',valuation_basis='SUPPLIED_FROZEN_MARKED_VALUES',group_ids=as.list(groups),states=list('A','B','D'),initial_values=lapply(groups,function(g)sum(vapply(bygroup[[g]],function(r)r$ead,numeric(1)))),terminal_values_by_grade=lapply(groups,function(g){e<-sum(vapply(bygroup[[g]],function(r)r$ead,numeric(1)));recovery<-sum(vapply(bygroup[[g]],function(r)r$ead*(1-forecast[[r$position_id]]$lgd),numeric(1)));list(e,e,recovery)}),cash_distributions=rep(list(as.list(rep(0,length(groups)))),length(scenario_ids)))
 migration<-simulate_portfolio_migrations(initial,rbind(c(.9,0,.1),c(0,.5,.5),c(0,0,1)),list(scenario_ids=as.list(scenario_ids),group_ids=as.list(groups),values=lapply(seq_len(nrow(uniforms)),function(i)list(as.list(1-uniforms[i,]))),weights=as.list(weights)),list(contract_id=paste0(product,'-migration'),version='1',group_ids=as.list(groups),states=list('A','B','D'),default_state='D',allow_cure=FALSE,probability_measure='PHYSICAL',time_grid=list(30),time_unit='days',matrix_mode='HOMOGENEOUS',innovation_law='CONDITIONALLY_UNIFORM_GIVEN_PRIOR_STATES'),valuation_contract=value_contract)$value
 factor<-residual<-list();stress_weights<-numeric();qvalues<-c(.05,.3,.75);qweights<-c(.1,.4,.5);for(j in seq_along(qvalues))for(i in seq_along(weights)){factor[[length(factor)+1L]]<-list(case$normal_coordinates[[sprintf('%.2f',qvalues[j])]]);residual[[length(residual)+1L]]<-lapply(uniforms[i,],function(x)case$normal_coordinates[[sprintf('%.2f',x)]]);stress_weights<-c(stress_weights,round(qweights[j]*weights[i],12))}
 normal_draws<-list(scenario_ids=as.list(paste0('normal-cell-',seq_along(factor)-1L)),weights=as.list(stress_weights),group_ids=as.list(groups),sampling_design='FIXED_WEIGHTED_SCENARIOS',factor_normals=factor,group_normals=residual);base_dep<-list(kind='GAUSSIAN_FACTORS',group_ids=as.list(groups),factor_ids=list('common'),factor_correlation=list(list(1)),loadings=rep(list(list(0)),length(groups)));stress_dep<-base_dep;stress_dep$loadings<-rep(list(list(1)),length(groups));stress_case<-list(case_id='perfect-common-factor',dependence_contract=stress_dep,group_pds=pds,conditional_loss_paths=paths(stress_dep,normal_draws),recovery_response='FIXED_PATHS')
 stress<-stress_portfolio_factor_structure(prepared,pds,base_dep,normal_draws,paths(base_dep,normal_draws),list(stress_case),levels=c(.8,.95))$value;expected<-sum(vapply(positions,function(p)p$ead*forecast[[p$position_id]]$pd*forecast[[p$position_id]]$lgd,numeric(1)));total<-sum(ead)
 benchmark<-asymptotic_factor_loss(sum(vapply(positions,function(p)p$ead*forecast[[p$position_id]]$pd,numeric(1)))/total,.4,0,c(-2,0,2))$value;target<-contract[c('event','horizon','time_unit','probability_measure','conditioning')];binding<-list(profile_id='retail-portfolio',profile_version='1',model_id=paste0(product,'-portfolio-dgp'),model_version='1',model_hash=content_fingerprint(list(pds=pds,dependence=dep,lgd=as.list(lgd)))$value,input_hash=prepared$portfolio_hash);components<-list(list(component_id='EL',quantity='EL',value=round(distribution$expected_loss,2),subject_id=product,subject_type='portfolio',variant='standalone',definition=target,currency='EUR'),list(component_id='EAD',quantity='EAD',value=total,subject_id=product,subject_type='portfolio',variant='standalone',definition=target,currency='EUR'));assessment<-compose_risk_assessment(paste0(product,'-portfolio-assessment'),list(subject_id=product,subject_type='portfolio'),components,binding,'2024-01-01','2024-01-01','2024-02-01')$value
 list(prepared=prepared,group_pds=pds,simulation=simulation,distribution=distribution,expected_shortfall_allocation=allocation,paired_facility_removal=removal,migration=migration,asymptotic_zero_correlation_benchmark=benchmark,stress=list(base_distribution=stress$base$distribution,stressed_distribution=stress$stress_cases[[1]]$stressed$distribution,paired_comparison=stress$stress_cases[[1]]$paired_comparison,shared_innovations_hash=stress$shared_innovations_hash,exact_endpoint_scope='Threshold event cells exact only for loadings zero and one; not a continuous-normal simulation sample'),assessment=assessment,assessment_monetary_rounding='EUR_CENTS',analytic_expected_loss=expected)
}
run_retail_portfolio_cases<-function(data=NULL,verify_reference=TRUE){
 if(is.null(data))data<-jsonlite::fromJSON(system.file('extdata/retail_portfolio_cases.json',package='creditratingsystem'),simplifyVector=FALSE);out<-list()
 for(product in names(data$cases)){
 case<-data$cases[[product]];fitargs<-case$pool_fit;fitargs$pooling_spec$segments<-lapply(fitargs$pooling_spec$segments,function(s){s$cutpoints<-unlist(s$cutpoints);s});fitted<-do.call(fit_retail_risk_pools,fitargs);assignments<-do.call(assign_retail_risk_pool,c(list(fitted_model=fitted),case$assignment_inputs));poolargs<-list(fitted_model=fitted,pool_assignments=assignments,assignment_inputs=case$assignment_inputs,predictions=case$predictions,cohort_outcomes=case$cohort_outcomes,workouts=case$workouts,links=case$links,estimation_profile=case$estimation_profile,design=case$design);clusters<-sort(unique(vapply(case$predictions,function(r)r$cluster_id,character(1))));resamples<-list(as.list(clusters),as.list(rev(clusters)),as.list(rep(clusters[1],length(clusters))),as.list(rep(tail(clusters,1),length(clusters))));diagnostics<-do.call(retail_pool_diagnostics,c(poolargs,list(uncertainty='cluster_bootstrap',cluster_resamples=resamples)))$value
 estimated<-estimate_pool_risk_parameters(assignments,case$cohort_outcomes,case$workouts,case$estimation_profile,evaluation_cutoff='2024-02-01',calibration_id=paste0(product,'-observed'),calibration_version='1')$value;estimated_summary<-lapply(estimated$pool_risk_table,function(row){row<-row[c('pool_id','pd','closed_workout_lgd','default_conditioned_ead','default_conditioned_ccf','open_workouts','missing_default_workouts')];for(k in names(row))if(is.list(row[[k]]))row[[k]]$independent_episode_standard_error<-NULL;row})
 drift<-detect_credit_feature_drift(lapply(case$pool_fit$observations,function(r)list(score=r$score)),lapply(case$assignment_inputs$observations,function(r)list(score=r$score)),feature_order='score',method='psi',permutations=NULL,multiple_testing='not_applicable',dependence_assumption='descriptive',frozen_bins=list(score=list(kind='numeric',cutpoints=c(25,50,75),support=c(0,100))))$value
 monitoring<-do.call(build_monitoring_cohorts,case$monitoring);early<-case$monitoring;early$evaluation_cutoff<-'2024-01-20';immature<-do.call(build_monitoring_cohorts,early)$value;missing<-case$monitoring;missing$coverage<-head(missing$coverage,-1);incomplete<-do.call(build_monitoring_cohorts,missing)$value
 summary<-monitor_rating_cohort(monitoring,group_by='cohort',reference_window=list(start='2024-01-01',end='2024-01-31'),minimum_count=10,uncertainty='independent_cluster_bootstrap',cluster_resamples=resamples)$value;countargs<-case$count_backtest;countargs$group_by<-unlist(countargs$group_by);counts<-do.call(default_count_backtest,countargs)$value;loss_design<-case$design;loss_design$target$conditioning<-'default'
 lgdtest<-lgd_backtest(case$loss_records,design=loss_design,workout_policy=list(method='closed_only',reference='Independent actual retail settlements; open claims excluded'),uncertainty='none')$value;eadtest<-ead_backtest(case$loss_records,design=loss_design,weighting_policy=list(method='equal',reference='Each observed defaulted facility once'),uncertainty='none')$value;vargs<-case$vintage;vargs$months_on_book<-unlist(vargs$months_on_book);vargs$delinquency_states<-unlist(vargs$delinquency_states);vargs$exit_events<-unlist(vargs$exit_events);vintage<-do.call(build_vintage_performance,vargs)$value
 risk<-.rpc_portfolio(case,product);concentration<-credit_concentration_measures(case$positions,weight_field='ead',group_fields='household_id',weight_unit='EUR')$value
 out[[product]]<-list(mechanism=case$mechanism,feature_drift=drift,pool_diagnostics=diagnostics,observed_pool_parameters=estimated_summary,pool_parameter_interval_policy='Independent-unit intervals omitted; household links retained in diagnostics',monitoring=monitoring$value,cohort_summary=summary,immature_cohort=immature,incomplete_negative_cohort=incomplete,default_count_backtest=counts,lgd_backtest=lgdtest,ead_backtest=eadtest,vintage=vintage,concentration=concentration,portfolio_risk=risk)
 if(verify_reference){pa<-(c(2,2,4,2,0)+.5)/12.5;pb<-(c(4,0,0,2,0)+.5)/8.5;stopifnot(abs(drift[[1]]$statistic-sum((pb-pa)*log(pb/pa)))<1e-12,counts$overall$observed_defaults==3,counts$overall$observed_count==6,!any(vapply(immature$rows,function(r)r$eligible,logical(1))),sum(vapply(incomplete$rows,function(r)r$eligible,logical(1)))==5,vintage[[1]]$cumulative_default_rate==.5,is.null(vintage[[2]]$cumulative_default_rate),abs(lgdtest$metrics$overall$ead_weighted$bias-.1)<1e-12,abs(eadtest$metrics$ead$overall$selected_weighting$bias+50*case$exposure_scale)<1e-8,abs(risk$distribution$expected_loss-risk$analytic_expected_loss)<1e-8,abs(sum(vapply(risk$expected_shortfall_allocation$contributions,function(r)r$contribution,numeric(1)))-risk$expected_shortfall_allocation$expected_shortfall)<1e-8,max(abs(unlist(risk$simulation$portfolio_loss_paths)-unlist(risk$migration$marked_values$portfolio_marked_loss_paths)))<1e-8,abs(risk$stress$base_distribution$expected_loss-risk$stress$stressed_distribution$expected_loss)<1e-8,all(abs(unlist(risk$asymptotic_zero_correlation_benchmark$conditional_loss_rate)*risk$prepared$total_ead-risk$analytic_expected_loss)<1e-8))}
 }
 list(product=data$product,data_origin=data$data_origin,version=data$version,cases=out)
}
